insert into ui_e2e_scene (
    id, project_id, application_id, environment_id, code, name, status, risk_level,
    source_summary_json, tags_json, created_by, updated_by, archived_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{applicationId}, #{environmentId}, #{code}, #{name}, #{status}, #{riskLevel},
    cast(coalesce(#{sourceSummaryJson}, '{}') as jsonb),
    cast(coalesce(#{tagsJson}, '[]') as jsonb),
    #{createdBy}, #{updatedBy}, #{archivedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
select 
from ui_e2e_scene
where id = #{id}

select 
from ui_e2e_scene
where project_id = #{projectId}
  and code = #{code}

select 
from ui_e2e_scene

order by updated_at desc, id desc
offset #{query.offset}
limit #{query.limit}

select project_id
from ui_e2e_scene
where id = #{id}

select 
from ui_e2e_bundle b
where id = #{id}

select 
from ui_e2e_bundle b
join ui_e2e_scene s on s.id = b.scene_id

order by b.updated_at desc, b.id desc
offset #{query.offset}
limit #{query.limit}

select project_id
from ui_e2e_bundle
where id = #{id}

