insert into ui_e2e_bundle_review (
    id, bundle_id, project_id, review_status, review_comment, reviewed_by, reviewed_at,
    created_by, updated_by, created_at, updated_at
) values (
    #{id}, #{bundleId}, #{projectId}, #{reviewStatus}, #{reviewComment}, #{reviewedBy}, #{reviewedAt},
    #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}
)

insert into ui_e2e_run (
    id, scene_id, bundle_id, project_id, status, request_key, runner_mode, base_url_digest,
    account_lease_ref, account_summary_json, execution_summary_json, failure_code, failure_summary, trace_id, created_by,
    started_at, finished_at, created_at, updated_at
) values (
    #{id}, #{sceneId}, #{bundleId}, #{projectId}, #{status}, #{requestKey}, #{runnerMode}, #{baseUrlDigest},
    #{accountLeaseRef}, cast(coalesce(#{accountSummaryJson}, '{}') as jsonb),
    cast(coalesce(#{executionSummaryJson}, '{}') as jsonb), #{failureCode}, #{failureSummary},
    #{traceId}, #{createdBy}, #{startedAt}, #{finishedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
select 
from ui_e2e_run r
where r.id = #{id}

select 
from ui_e2e_run r
where r.project_id = #{projectId}
  and r.scene_id = #{sceneId}
  and r.request_key = #{requestKey}
order by r.created_at desc, r.id desc
limit 1

select 
from ui_e2e_run r
join ui_e2e_scene s on s.id = r.scene_id

order by r.updated_at desc, r.id desc
offset #{query.offset}
limit #{query.limit}

select project_id
from ui_e2e_run
where id = #{id}

